function currencyInfo(){let saved="";try{saved=localStorage.getItem("glow15_currency")||""}catch(_){}const l=LANG();const code=saved||(["fr","es","pt","de","it"].includes(l)?"EUR":"GBP");const rates={GBP:1,EUR:1.165,USD:1.34};return {code:rates[code]?code:"GBP",rate:rates[code]||1};}
function moneyFromGbp(v){const x=currencyInfo();const locale=x.code==="EUR"?"en-IE":x.code==="USD"?"en-US":"en-GB";return new Intl.NumberFormat(locale,{style:"currency",currency:x.code,maximumFractionDigits:0}).format(Number(v)*x.rate);}
