function scan(){
 const x=c();setHead(x.scan);tabs("scan");
 $("g15body").innerHTML=`<div class="g15-photo-guide"><div class="g15-product-icon">▧</div><h3>${x.scan}</h3><p>${x.photoHint}</p><p class="g15-note"><b>${e1("whyScanFront")}</b><br>${e1("whyScanBack")}</p></div><div class="g15-upload-grid"><div class="g15-upload"><span>+</span><b>${x.front}</b><small>${e1("whyScanFront")}</small><div class="g15-upload-actions"><button type="button" class="g15-outline" id="g15img1Cam">${e1("camera")}</button><button type="button" class="g15-outline" id="g15img1Gallery">${e1("gallery")}</button></div><input id="g15img1" type="file" accept="image/*" capture="environment" hidden><input id="g15img1g" type="file" accept="image/*" hidden></div><div class="g15-upload"><span>+</span><b>${x.back}</b><small>${e1("whyScanBack")}</small><div class="g15-upload-actions"><button type="button" class="g15-outline" id="g15img2Cam">${e1("camera")}</button><button type="button" class="g15-outline" id="g15img2Gallery">${e1("gallery")}</button></div><input id="g15img2" type="file" accept="image/*" capture="environment" hidden><input id="g15img2g" type="file" accept="image/*" hidden></div></div><div class="g15-preview" id="g15previews"></div><button class="g15-primary" id="g15analyse">${x.scanNow} →</button><p class="g15-note">${x.notMedical}</p>`;
 const setProductImage=async(e,target)=>{const f=e.target.files?.[0];if(!f)return;const idx=target==="g15img1"?0:1;try{images[idx]=await fileData(f);renderPreviews();}catch(err){alert(err?.message||c().failed)}finally{e.target.value=""}};[["g15img1","g15img1"],["g15img1g","g15img1"],["g15img2","g15img2"],["g15img2g","g15img2"]].forEach(([id,target])=>$(id).onchange=e=>setProductImage(e,target));$("g15img1Cam").onclick=()=>$("g15img1").click();$("g15img1Gallery").onclick=()=>$("g15img1g").click();$("g15img2Cam").onclick=()=>$("g15img2").click();$("g15img2Gallery").onclick=()=>$("g15img2g").click();
 $("g15analyse").onclick=analyse;
}
function renderPreviews(){$("g15previews").innerHTML=images.filter(Boolean).map((im,i)=>`<div><img src="${im}" alt=""><small>${i===0?c().front:c().back}</small></div>`).join("")}
async function analyse(){
 const x=c();if(!images.filter(Boolean).length){alert(x.photoHint);return}
 if(!journeyId){home();const e=$("g15JourneyError");if(e)e.textContent=h1("productError");return}
 $("g15analyse").disabled=true;$("g15analyse").textContent=x.working;
 try{
  const r=await fetch(API+"/glow15-product-scan",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({journeyId,images:images.filter(Boolean),language:LANG()})});
  const d=await r.json();if(!r.ok)throw Error(d.error||x.failed);lastProduct=d.product;view="result";renderResult();
 }catch(e){alert(e.message||x.failed)}finally{if($("g15analyse")){$("g15analyse").disabled=false;$("g15analyse").textContent=x.scanNow}}
}
function scoreClass(n){return n>=76?"high":n>=51?"mid":"low"}
function list(items){return (Array.isArray(items)?items:[]).map(v=>`<li>${esc(v)}</li>`).join("")}
function renderResult(){
 const x=c(),q=p1c(),p=lastProduct;setHead(p.product_name||x.scan);tabs("scan");
 var caution=p.cautions?.length?"<section class=\"g15-caution\"><h4>"+x.caution+"</h4><ul>"+list(p.cautions)+"</ul></section>":"";
 var html="<article class=\"g15-result\"><div class=\"g15-result-top\"><div><div class=\"g15-kicker\">"+esc(p.brand||"PRODUCT")+"</div><h3>"+esc(p.product_name)+"</h3><p>"+esc(p.category)+" · "+esc(p.format||"")+"</p></div><div class=\"g15-fit "+scoreClass(Number(p.fit_score||0))+"\"><strong>"+(p.fit_score??"—")+"</strong><span>/100</span><small>"+x.fit+"</small></div></div><div class=\"g15-signal-row\"><span>"+x.safety+": <b>"+esc(p.safety_level)+"</b></span><span>"+x.confidence+": <b>"+esc(p.scan_confidence)+"</b></span></div><section class=\"g15-section\"><h4>"+x.why+"</h4><ul>"+list(p.fit_reasons)+"</ul></section>"+caution+"<section class=\"g15-two\"><div><h4>"+x.best+"</h4><ul>"+list(p.best_for)+"</ul></div><div><h4>"+x.alt+"</h4><ul>"+list(p.alternative_profile)+"</ul></div></section><section class=\"g15-section\"><h4>"+x.application+"</h4><p>"+esc(p.application||e1("followLabel"))+"</p></section><button class=\"g15-primary\" id=\"g15add\">"+x.add+" →</button><button class=\"g15-outline\" id=\"g15alts\">"+q.alternatives+"</button></article>";
 $("g15body").innerHTML=html;$("g15add").onclick=addToShelf;$("g15alts").onclick=function(){showAlternatives(p)};
}
async function addToShelf(){
 const x=c();if(!lastProduct)return;
 if(demo){products.unshift({...lastProduct,id:"demo-"+Date.now()});products=products.slice(0,20);openView("shelf");return}
 const r=await fetch(API+"/glow15-shelf",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({journeyId,product:lastProduct})});const d=await r.json();if(!r.ok){alert(d.error||x.failed);return}openView("shelf");
}
async function loadShelf(){
 if(demo){return}
 const r=await fetch(API+"/glow15-shelf?journey_id="+encodeURIComponent(journeyId));const d=await r.json();if(r.ok)products=d.products||[];else throw Error(d.error||c().noJourney);
}
async function loadP1(productId){
 if(demo){p1={budget:50,wishlist:[],routine:{am:[],pm:[]}};return}
 var url=API+"/glow15-p1?journey_id="+encodeURIComponent(journeyId)+(productId?"&product_id="+encodeURIComponent(productId):"");
 var r=await fetch(url),d=await r.json();if(!r.ok)throw Error(d.error||c().noJourney);
 p1={budget:Number(d.budget||50),wishlist:d.wishlist||[],routine:d.routine||{am:[],pm:[]},recommendations:d.recommendations||{budget:Number(d.budget||50),recommendations:[],total:0,remainingBudget:Number(d.budget||50),gapCount:0}};return d;
}
